package silo.lib.quality

import rego.v1

rank := {
	"": 0,
	"480P": 1,
	"720P": 2,
	"1080P": 3,
	"2160P": 4,
	"4320P": 5,
}

normalize(value) := normalized if {
	u := upper(trim(sprintf("%v", [value]), " "))
	u == ""
	normalized := ""
} else := normalized if {
	u := upper(trim(sprintf("%v", [value]), " "))
	u == "ANY"
	normalized := ""
} else := normalized if {
	u := upper(trim(sprintf("%v", [value]), " "))
	u in {"STANDARD", "480P", "720P", "1080P"}
	normalized := "1080p"
} else := normalized if {
	u := upper(trim(sprintf("%v", [value]), " "))
	u in {"4K", "UHD", "2160P", "4320P"}
	normalized := "2160p"
} else := ""

compare(a, b) := -1 if {
	rank[upper(trim(normalize(a), " "))] < rank[upper(trim(normalize(b), " "))]
} else := 1 if {
	rank[upper(trim(normalize(a), " "))] > rank[upper(trim(normalize(b), " "))]
} else := 0

allowed(file_quality, ceiling) if {
	normalize(ceiling) == ""
} else if {
	file_rank := object.get(rank, raw(file_quality), 0)
	ceiling_rank := object.get(rank, upper(trim(normalize(ceiling), " ")), 0)
	file_rank <= ceiling_rank
}

raw(value) := upper(trim(sprintf("%v", [value]), " "))

min(a, b) := result if {
	normalized_a := normalize(a)
	trim(normalized_a, " ") == ""
	result := normalize(b)
} else := result if {
	normalized_b := normalize(b)
	trim(normalized_b, " ") == ""
	result := normalize(a)
} else := result if {
	compare(a, b) <= 0
	result := normalize(a)
} else := normalize(b)

package silo.lib.ratings

import rego.v1

rank := {
	"G": 0,
	"TV-Y": 0,
	"TV-G": 0,
	"PG": 1,
	"TV-Y7": 1,
	"TV-PG": 1,
	"PG-13": 2,
	"TV-14": 2,
	"R": 4,
	"NC-17": 4,
	"TV-MA": 4,
	"AU-G": 0,
	"AU-PG": 1,
	"AU-M": 2,
	"AU-MA15+": 3,
	"AU-R18+": 4,
	"AU-X18+": 5,
}

normalize(value) := upper(trim(sprintf("%v", [value]), " "))

allowed(rating, ceiling) if {
	normalize(ceiling) == ""
} else if {
	rating_value := rank[normalize(rating)]
	ceiling_value := rank[normalize(ceiling)]
	rating_value <= ceiling_value
}

min(a, b) := result if {
	normalize(a) == ""
	result := normalize(b)
} else := result if {
	normalize(b) == ""
	result := normalize(a)
} else := result if {
	not rank[normalize(a)]
	result := normalize(a)
} else := result if {
	not rank[normalize(b)]
	result := normalize(b)
} else := result if {
	rank[normalize(a)] <= rank[normalize(b)]
	result := normalize(a)
} else := normalize(b)

package silo.permission

import rego.v1

decision := tightened if {
	override := data.silo_custom.permission.override(base_decision, input)
	tightened := tighten(base_decision, override)
} else := base_decision

base_decision := acting_admin_decision(input) if {
	input.permission == "acting_admin"
} else := marker_edit_decision(input) if {
	input.permission == "marker_edit"
} else := metadata_curation_decision(input) if {
	input.permission == "metadata_curation"
} else := deny("unknown permission", "unknown_permission")

acting_admin_decision(i) := allow if {
	acting_admin_allowed(i)
} else := deny("user disabled", "user_disabled") if {
	not user_enabled(i)
} else := deny("admin role required", "admin_role_required") if {
	not admin_role(i)
} else := deny("primary profile required", "primary_profile_required")

marker_edit_decision(i) := allow if {
	effective_permission_allowed(i, "marker_edit")
} else := deny("user disabled", "user_disabled") if {
	not user_enabled(i)
} else := deny("marker edit permission required", "marker_edit_permission_required")

metadata_curation_decision(i) := allow if {
	acting_admin_allowed(i)
} else := allow if {
	user_enabled(i)
	assigned_permission(i, "metadata_curation")
	target_libraries_allowed(i)
} else := deny("user disabled", "user_disabled") if {
	not user_enabled(i)
} else := deny("metadata curation permission required", "metadata_curation_permission_required") if {
	not assigned_permission(i, "metadata_curation")
} else := deny("item is outside user libraries", "item_outside_user_libraries")

effective_permission_allowed(i, permission) if {
	user_enabled(i)
	assignable_permission(permission)
	admin_role(i)
} else if {
	user_enabled(i)
	assigned_permission(i, permission)
}

acting_admin_allowed(i) if {
	user_enabled(i)
	admin_role(i)
	declared_profile_id(i) == ""
} else if {
	user_enabled(i)
	admin_role(i)
	declared_profile_id(i) != ""
	acting_as_primary(i)
}

target_libraries_allowed(i) if {
	count(target_library_ids(i)) > 0
	not user_libraries_restricted(i)
} else if {
	count(target_library_ids(i)) > 0
	user_libraries_restricted(i)
	every id in target_library_ids(i) {
		has_value(user_library_ids(i), id)
	}
}

assignable_permission("marker_edit")
assignable_permission("metadata_curation")

assigned_permission(i, permission) if {
	some idx
	assigned_permissions(i)[idx] == permission
}

admin_role(i) if {
	role(i) == "admin"
}

user_enabled(i) if {
	object.get(i, "user_enabled", false) == true
}

acting_as_primary(i) if {
	object.get(i, "acting_as_primary", false) == true
}

user_libraries_restricted(i) if {
	object.get(i, "user_libraries_restricted", false) == true
}

role(i) := object.get(i, "role", "")

declared_profile_id(i) := object.get(i, "declared_profile_id", "")

assigned_permissions(i) := values if {
	values := object.get(i, "assigned_permissions", [])
	is_array(values)
} else := []

target_library_ids(i) := values if {
	values := object.get(i, "target_library_ids", [])
	is_array(values)
} else := []

user_library_ids(i) := values if {
	values := object.get(i, "user_library_ids", [])
	is_array(values)
} else := []

has_value(values, value) if {
	some i
	values[i] == value
}

allow := {
	"allowed": true,
	"reason": "allowed",
	"reason_code": "",
}

# reason is human-readable free text; reason_code is the machine contract Go
# consumers switch on (see policy.ReasonCode* constants).
deny(reason, code) := {
	"allowed": false,
	"reason": reason,
	"reason_code": code,
}

tighten(base, override) := result if {
	allowed := tightened_allowed(base, override)
	reason := tightened_reason(base, override, allowed)
	reason_code := tightened_reason_code(base, override, allowed)
	result := {
		"allowed": allowed,
		"reason": reason,
		"reason_code": reason_code,
	}
}

# Only a literal boolean true keeps the base grant; any other override value
# (including malformed non-boolean output) tightens to a deny.
override_grants(override) if {
	object.get(override, "allowed", true) == true
}

tightened_allowed(base, override) := true if {
	base.allowed
	override_grants(override)
} else := false

tightened_reason(base, override, allowed) := reason if {
	not allowed
	base.allowed
	not override_grants(override)
	reason := nonempty_string_or_default(object.get(override, "reason", ""), base.reason)
} else := base.reason

# Overrides only carry free-text reasons, so a custom deny always gets the
# fixed custom_denial code; a base deny keeps its vendor code.
tightened_reason_code(base, override, allowed) := "custom_denial" if {
	not allowed
	base.allowed
	not override_grants(override)
} else := object.get(base, "reason_code", "")

nonempty_string_or_default(value, fallback) := value if {
	is_string(value)
	value != ""
} else := fallback

package silo.scope

import rego.v1
import data.silo.lib.quality
import data.silo.lib.ratings

decision := tightened if {
	override := data.silo_custom.scope.override(base_decision, input)
	tightened := tighten(base_decision, override)
} else := base_decision

base_decision := decision if {
	libraries := library_decision(input)
	decision := {
		"schema_version": input.schema_version,
		"unrestricted": libraries.unrestricted,
		"allowed_library_ids": libraries.allowed_library_ids,
		"disabled_library_ids": libraries.disabled_library_ids,
		"libraries_restricted": libraries.libraries_restricted,
		"max_content_rating": max_content_rating(input),
		"max_playback_quality": max_playback_quality(input),
		"preferred_metadata_language": preferred_metadata_language(input),
		"policy_revision": input.access_policy_revision,
		"profile_verified": input.profile_verified,
	}
}

library_decision(i) := result if {
	effective := effective_libraries(i)
	effective.unrestricted
	result := {
		"unrestricted": true,
		"allowed_library_ids": [],
		"disabled_library_ids": disabled_ids(i),
		"libraries_restricted": false,
	}
} else := result if {
	effective := effective_libraries(i)
	not effective.unrestricted
	result := {
		"unrestricted": false,
		"allowed_library_ids": subtract(effective.allowed_library_ids, disabled_ids(i)),
		"disabled_library_ids": [],
		"libraries_restricted": true,
	}
}

effective_libraries(i) := result if {
	i.account_restricted
	i.profile_present
	i.profile_library_restricted
	result := {
		"unrestricted": false,
		"allowed_library_ids": intersect(i.account_library_ids, i.profile_allowed_library_ids),
	}
} else := result if {
	i.account_restricted
	not profile_limits_libraries(i)
	result := {
		"unrestricted": false,
		"allowed_library_ids": array_or_empty(i.account_library_ids),
	}
} else := result if {
	not i.account_restricted
	i.profile_present
	i.profile_library_restricted
	result := {
		"unrestricted": false,
		"allowed_library_ids": unique_sorted(i.profile_allowed_library_ids),
	}
} else := {
	"unrestricted": true,
	"allowed_library_ids": [],
}

profile_limits_libraries(i) if {
	i.profile_present
	i.profile_library_restricted
}

max_content_rating(i) := rating if {
	i.profile_present
	rating := i.profile_max_content_rating
} else := ""

max_playback_quality(i) := quality.min(i.account_max_playback_quality, profile_quality(i))

profile_quality(i) := quality if {
	i.profile_present
	quality := i.profile_max_playback_quality
} else := ""

preferred_metadata_language(i) := language if {
	i.profile_present
	language := i.profile_preferred_metadata_language
} else := ""

disabled_ids(i) := ids if {
	is_array(i.disabled_library_ids)
	ids := i.disabled_library_ids
} else := []

array_or_empty(xs) := xs if {
	is_array(xs)
} else := []

intersect(left, right) := unique_sorted([id |
	some i
	id := right[i]
	has_value(left, id)
])

unique_sorted(values) := sort({id |
	some i
	id := values[i]
})

subtract(values, excluded) := [id |
	some i
	id := values[i]
	not has_value(excluded, id)
]

has_value(values, value) if {
	some i
	values[i] == value
}

tighten(base, override) := result if {
	unrestricted := merged_unrestricted(base, override)
	disabled := merged_disabled(base, override)
	allowed := merged_allowed(base, override, unrestricted, disabled)
	libraries_restricted := restricted(unrestricted)
	max_rating := ratings.min(base["max_content_rating"], object.get(override, "max_content_rating", ""))
	max_quality := quality.min(base["max_playback_quality"], object.get(override, "max_playback_quality", ""))
	profile_verified := merged_profile_verified(base, override)
	output_disabled := disabled_if_unrestricted(disabled, unrestricted)
	result := {
		"schema_version": base["schema_version"],
		"unrestricted": unrestricted,
		"allowed_library_ids": allowed,
		"disabled_library_ids": output_disabled,
		"libraries_restricted": libraries_restricted,
		"max_content_rating": max_rating,
		"max_playback_quality": max_quality,
		"preferred_metadata_language": base["preferred_metadata_language"],
		"policy_revision": base["policy_revision"],
		"profile_verified": profile_verified,
	}
}

restricted(unrestricted) := false if {
	unrestricted
} else := true

merged_unrestricted(base, override) := true if {
	base.unrestricted
	object.get(override, "unrestricted", base.unrestricted)
} else := false

merged_profile_verified(base, override) := true if {
	base.profile_verified
	object.get(override, "profile_verified", true)
} else := false

merged_disabled(base, override) := unique_sorted(array.concat(
	object.get(base, "disabled_library_ids", []),
	object.get(override, "disabled_library_ids", []),
))

merged_allowed(base, override, unrestricted, disabled) := [] if {
	unrestricted
} else := allowed if {
	not unrestricted
	base.unrestricted
	not object.get(override, "unrestricted", base.unrestricted)
	allowed := subtract(object.get(override, "allowed_library_ids", []), disabled)
} else := allowed if {
	not unrestricted
	not base.unrestricted
	object.get(override, "unrestricted", base.unrestricted)
	allowed := subtract(base.allowed_library_ids, disabled)
} else := allowed if {
	not unrestricted
	not base.unrestricted
	not object.get(override, "unrestricted", base.unrestricted)
	allowed := subtract(intersect(base.allowed_library_ids, object.get(override, "allowed_library_ids", [])), disabled)
}

disabled_if_unrestricted(disabled, unrestricted) := disabled if {
	unrestricted
} else := []
